"""Conservative, hysteretic closed-loop controller for the Last10mPolicy."""

# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety gating, short target confirmation, and stable bearing control."""
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    scan_age = int(memory.get("scan_age", 0))
    last_action = memory.get("last_action", "STOP")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_conf = float(observation["target_confidence"])
    identity_conf = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_conf = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = abs(float(observation["heading_error"]))

    def remember(action, next_state, confidence):
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    # Safety is an unconditional hard gate.
    if safety_conf < 0.60 or closing_risk >= 0.75:
        return remember("STOP", "STOPPED", 0.99)

    confirmed = visible and target_conf >= 0.55 and identity_conf >= 0.60

    if not confirmed:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps > 0:
            if lost_steps <= 1:
                return remember("STOP", "REACQUIRE", 0.92)
            # Keep a scan direction briefly to avoid left/right chatter.
            if scan_age < 2:
                memory["scan_age"] = scan_age + 1
                return remember(scan_direction, "SEARCH", 0.76)
            scan_direction = (
                "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
            )
        memory["scan_direction"] = scan_direction
        memory["scan_age"] = 0
        return remember(scan_direction, "SEARCH", 0.75)

    memory["scan_age"] = 0

    # A newly acquired track gets one cautious confirmation step.
    if track_age <= 0:
        return remember("SLOW_DOWN", "VERIFY", 0.80)

    if closing_risk >= 0.60:
        return remember("SLOW_DOWN", "APPROACH", 0.84)

    # Require a strong, well-aligned near observation before declaring arrival.
    if (
        distance == "near"
        and heading_error <= 12.0
        and identity_conf >= 0.84
        and target_conf >= 0.68
    ):
        return remember("ARRIVED", "ARRIVED", 0.97)

    if distance == "near":
        action = "VEER_LEFT" if bearing < 0 else "VEER_RIGHT"
        return remember(action, "APPROACH", 0.87)

    # Use a modest deadband to prevent oscillation around the target bearing.
    if bearing <= -12.0 and observation["corridor_left"]:
        return remember("VEER_LEFT", "APPROACH", 0.90)
    if bearing >= 12.0 and observation["corridor_right"]:
        return remember("VEER_RIGHT", "APPROACH", 0.90)
    if observation["corridor_center"]:
        return remember("FORWARD", "APPROACH", 0.91)

    # If centered travel is unavailable, choose the available side with
    # preference for continuing the previous turn.
    if observation["corridor_left"] and observation["corridor_right"]:
        action = last_action if last_action in {"VEER_LEFT", "VEER_RIGHT"} else (
            "VEER_LEFT" if bearing < 0 else "VEER_RIGHT"
        )
        return remember(action, "APPROACH", 0.83)
    if observation["corridor_left"]:
        return remember("VEER_LEFT", "APPROACH", 0.82)
    if observation["corridor_right"]:
        return remember("VEER_RIGHT", "APPROACH", 0.82)

    return remember("STOP", "STOPPED", 0.98)
# EVOLVE-BLOCK-END
